702	    /**
703	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
704	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
705	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
706	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
707	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
708	     * membership level is derived from (see {@link #getMembershipLevel()}).
709	     *
710	     * @return the owner's membership points
711	     */
712	    @Transient
713	    public Integer getMembershipPoints() {
714	        LocalDate today = LocalDate.now();
715	        int points = 0;
716	        if (hasEmail(this.email)) {
717	            points += 2;
718	        }
719	        if (hasNoNamesakes(this.namesakeCount)) {
720	            points += 1;
721	        }
722	        if (hasLargeHousehold(this.householdMemberCount)) {
723	            points += 2;
724	        }
725	        if (hasLongTenure(this.registrationDate, today)) {
726	            points += 3;
727	        }
728	        return points;
