811	    /**
812	     * Computes the single Luhn check digit (0-9) over the digits contained in a string: reading from
813	     * the right, every second digit is doubled (subtracting 9 when the result exceeds 9), the digits
814	     * are summed and the check digit is the amount that rounds the sum up to the next multiple of ten.
815	     * Non-digit characters are skipped, so a code mixing letters and digits contributes only its
816	     * digits. This is the single definition of the Luhn check digit, shared by every value that
817	     * carries one (the {@code CHK} segment of the unified member id, see {@link #getMemberId()}).
818	     *
819	     * @param code the string whose digits the check digit is computed over
820	     * @return the Luhn check digit (0-9) of {@code code}
821	     */
822	    public static int luhnCheckDigit(String code) {
823	        int sum = 0;
824	        boolean dbl = true;
825	        for (int i = code.length() - 1; i >= 0; i--) {
826	            char c = code.charAt(i);
827	            if (c < '0' || c > '9') {
828	                continue;
829	            }
830	            int d = c - '0';
831	            if (dbl) {
832	                d *= 2;
833	                if (d > 9) {
834	                    d -= 9;
835	                }
836	            }
837	            sum += d;
838	            dbl = !dbl;
839	        }
840	        return (10 - (sum % 10)) % 10;
841	    }
