361	     * @param owner the persisted owner to render
362	     * @return the {@code 200 OK} response carrying the owner representation
363	     */
364	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
365	        applyHouseholdMemberCount(owner);
