547	    /**
548	     * Applies an owner's address to the submitted fields, normalizing it in place into the
549	     * canonical form stored and returned for the owner. This is the single intake step that owns
550	     * how a submitted address becomes an owner's stored address: it delegates every transform to
551	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
552	     * the results back onto {@code ownerFieldsDto}.
553	     *
554	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
555	     * is present the two structured lines are normalized in place and the flat {@code address} is
556	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
557	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
558	     * every rule that later reads {@code address} sees the structured value. When no structured
559	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
560	     * backward compatibility.
561	     *
562	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
563	     * blank after normalization in either form is rejected by the required-field check that
564	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
565	     * list of named intake steps and gives address handling one place to grow.
566	     *
567	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
568	     */
569	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
570	        String line1 = ownerFieldsDto.getAddressLine1();
571	        if (line1 != null && !line1.isBlank()) {
572	            String normalizedLine1 = normalizeAddress(line1);
573	            ownerFieldsDto.setAddressLine1(normalizedLine1);
574	            String line2 = ownerFieldsDto.getAddressLine2();
575	            if (line2 != null && !line2.isBlank()) {
576	                String normalizedLine2 = normalizeAddress(line2);
577	                ownerFieldsDto.setAddressLine2(normalizedLine2);
578	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
579	            } else {
580	                ownerFieldsDto.setAddressLine2(null);
581	                ownerFieldsDto.setAddress(normalizedLine1);
582	            }
583	        } else {
584	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
585	        }
586	    }
