588	    /**
589	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
590	     * falls on a business day. The date supplied on the request is used when present, otherwise the
591	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
592	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
593	     * is left unchanged. This single adjusted date
594	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
595	     * membership number's year segment, the per-day create limit) is computed against.
596	     *
597	     * A supplied registration date later than the server's current date is rejected with an
598	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
599	     *
600	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
601	     * @return the effective registration date rolled forward to the next business day
602	     */
603	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
604	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
605	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
606	            throw new InvalidFieldsException(List.of("registrationDate"));
607	        }
608	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
609	        return toBusinessDay(effective);
610	    }
611	
612	    /**
613	     * The fixed public holidays the business-day roll skips. A date landing on any of these is
614	     * advanced, along with weekends, until it reaches the next non-holiday business day.
615	     */
616	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
617	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
618	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
619	        LocalDate.parse("2026-12-28"));
620	
621	    /**
622	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public holiday is
623	     * advanced one day at a time until it reaches a weekday that is not a public holiday, while a
624	     * date already on such a business day is returned unchanged.
625	     *
626	     * @param date the date to adjust
627	     * @return the same date when it is a non-holiday weekday, otherwise the next such business day
628	     */
629	    private LocalDate toBusinessDay(LocalDate date) {
630	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
631	                || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
632	                || PUBLIC_HOLIDAYS.contains(date)) {
633	            date = date.plusDays(1);
634	        }
635	        return date;
636	    }
