638	    /**
639	     * The maximum number of owners that may be created on a single day. Once this many owners
640	     * already carry today's {@code registrationDate}, no further owner may be created today.
641	     */
642	    private static final long DAILY_OWNER_LIMIT = 100L;
643	
644	    /**
645	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
646	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
647	     * date the new owner would be stored with, so owners are capped per business day. When the limit
648	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
649	     * advice renders as a 429 Too Many Requests response.
650	     *
651	     * @param registrationDate the adjusted business-day registration date of the owner being created
652	     */
653	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
654	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
655	            throw new DailyOwnerLimitExceededException(registrationDate);
656	        }
