662	     * create limit ({@link #rejectDailyLimitExceeded(LocalDate)}) and the bulk-signup warning
663	     * ({@link #bulkSignupWarning(LocalDate)}), so both accumulate owners against a day identically.
664	     *
665	     * @param registrationDate the adjusted business-day registration date to count owners against
666	     * @return the number of existing owners carrying that registration date
667	     */
668	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
669	        return this.clinicService.findAllOwners().stream()
670	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
671	            .count();
