675	     * The number of owners that may carry a single day's {@code registrationDate} before that day
676	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
677	     * the create and read responses report {@code bulkSignupWarning} true for that date.
678	     */
679	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
