697	    /**
698	     * The maximum number of owners a single city may hold. Once a city already contains this
699	     * many owners, no further owner may be created in it.
700	     */
701	    private static final long CITY_OWNER_CAPACITY = 50L;
702	
703	    /**
704	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
705	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
706	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
707	     * which the exception advice renders as a 409 Conflict response.
708	     *
709	     * @param city the city of the owner being created
710	     */
711	    private void rejectCityAtCapacity(String city) {
