717	    /**
718	     * Counts the existing owners whose {@code city} equals the given city, compared
719	     * case-insensitively. This is the single definition of the per-city owner count, shared by the
720	     * hard capacity rejection ({@link #rejectCityAtCapacity(String)}) and the approaching-capacity
721	     * warning ({@link #capacityWarning(String)}), so both measure a city's occupancy identically.
722	     *
723	     * @param city the city to count owners against
724	     * @return the number of existing owners whose city matches
725	     */
726	    private long countOwnersInCity(String city) {
727	        return this.clinicService.findAllOwners().stream()
728	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
729	            .count();
730	    }
