757	    /**
758	     * Builds the unified {@code memberId} assigned to a newly created owner. The id is formatted as
759	     * {@code '<REGION><FY><HASH8><CHK>'}, concatenating (with no separators) the owner's identity
760	     * region code (see {@link Owner#getIdentityRegionCode()}, rendered {@code 'UNKNOWN'} when the
761	     * owner has no known region), the two-digit fiscal-year segment its business-day-adjusted {@code registrationDate}
762	     * falls in (see {@link Owner#fiscalYearSegment(LocalDate)}), its identity hash (see
763	     * {@link Owner#getIdentityHash()}, the first 8 upper-case hex characters of the SHA-256 digest
764	     * over the owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}) and
765	     * a single Luhn check digit (see {@link Owner#luhnCheckDigit(String)}) computed over the digits of
766	     * {@code <REGION><FY><HASH8>}. The composed base is then de-duplicated against existing owners
767	     * (see {@link #deduplicateMemberId(String)}). The base carries no sequence number, so two owners
768	     * sharing a region, fiscal year, telephone and last name resolve to the same base and are
769	     * separated only by de-duplication.
770	     *
771	     * @param owner the owner being created, whose fields the id is derived from
772	     * @return the formatted member id
773	     */
774	    private String memberIdFor(Owner owner) {
775	        String prefix = owner.getIdentityRegionCode()
776	            + Owner.fiscalYearSegment(owner.getRegistrationDate())
777	            + owner.getIdentityHash();
778	        return deduplicateMemberId(prefix + Owner.luhnCheckDigit(prefix));
779	    }
780	
781	    /**
782	     * Ensures the computed {@code memberId} is unique across existing owners. When the given base id
783	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
784	     * {@code n} of 2 or more that yields an id no existing owner already carries.
785	     *
786	     * @param baseCode the member id computed for the owner being created
787	     * @return the base id when it is already unique, otherwise the de-duplicated id
788	     */
789	    private String deduplicateMemberId(String baseCode) {
790	        Set<String> existing = this.clinicService.findAllOwners().stream()
791	            .map(Owner::getMemberId)
792	            .filter(Objects::nonNull)
793	            .collect(Collectors.toSet());
794	        if (!existing.contains(baseCode)) {
795	            return baseCode;
796	        }
797	        int n = 2;
798	        while (existing.contains(baseCode + "-" + n)) {
799	            n++;
800	        }
801	        return baseCode + "-" + n;
802	    }
