804	    /**
805	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
806	     * with the owner being created, compared case-insensitively. The count is taken before the
807	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
808	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
809	     *
810	     * @param firstName the first name of the owner being created
811	     * @param lastName the last name of the owner being created
812	     * @return the number of pre-existing owners sharing the same first and last name
813	     */
814	    private int countNamesakes(String firstName, String lastName) {
815	        return (int) this.clinicService.findAllOwners().stream()
816	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
817	                && lastName.equalsIgnoreCase(existing.getLastName()))
818	            .count();
819	    }
