63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final HttpServletRequest request;
85	
86	    /**
87	     * HTTP header carrying the client-supplied idempotency key for the create endpoint. When a
88	     * create repeats with a key already seen, the originally created owner is returned instead of
89	     * creating a duplicate.
90	     */
91	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
92	
93	    /**
94	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that key's create produced,
95	     * so a repeat create with the same key can return the originally created owner rather than
96	     * persisting a duplicate. Shared across requests, hence concurrency-safe.
97	     */
98	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
99	
100	    /**
101	     * Source of the {@code seq} carried by each structured {@code OWNER_CREATED} audit event: a
102	     * monotonically increasing integer stamped once per successful create, in creation order.
103	     * Shared across requests, hence concurrency-safe.
104	     */
105	    private static final AtomicLong OWNER_CREATED_SEQ = new AtomicLong(0);
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 HttpServletRequest request) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.request = request;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return okOwnerResponse(owner);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = idempotencyKey();
148	        if (idempotencyKey != null) {
149	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
150	            if (replay != null) {
151	                return replay;
152	            }
153	        }
154	        Owner owner = createOwner(ownerFieldsDto);
155	        if (idempotencyKey != null) {
156	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
157	        }
158	        return createdOwnerResponse(owner);
159	    }
160	
161	    /**
162	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
163	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
164	     * create proceeds normally.
165	     *
166	     * @return the non-blank idempotency key, or {@code null} when none was supplied
167	     */
168	    private String idempotencyKey() {
169	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
170	        if (key == null || key.isBlank()) {
171	            return null;
172	        }
173	        return key.trim();
174	    }
175	
176	    /**
177	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
178	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
179	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
180	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
181	     * normally.
182	     *
183	     * @param idempotencyKey the non-blank idempotency key supplied on the request
184	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
185	     */
186	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
187	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
188	        if (existingId == null) {
189	            return null;
190	        }
191	        Owner existing = this.clinicService.findOwnerById(existingId);
192	        if (existing == null) {
193	            return null;
194	        }
195	        return okOwnerResponse(existing);
196	    }
197	
198	    /**
199	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
200	     * the saved {@link Owner}. The submitted fields are normalized and validated
201	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
202	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
203	     * then mapped, stamped with that registration date and every derived value (member id,
204	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
205	     * finally stamped with its household member count. A rule that rejects the owner signals it by
206	     * throwing, which the exception advice renders as the matching 4xx response, so this method
207	     * returns only for an owner that was accepted and persisted. The create is audited once the
208	     * owner has its identity.
209	     *
210	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
211	     * {@link #createdOwnerResponse(Owner)}.
212	     *
213	     * @param ownerFieldsDto the submitted owner fields, normalized in place
214	     * @return the persisted owner
215	     */
216	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
217	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
218	        prepareNewOwner(ownerFieldsDto, registrationDate);
219	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
220	        owner.setRegistrationDate(registrationDate);
221	        owner.setMemberId(memberIdFor(owner));
222	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
223	        assignHousehold(owner);
224	        applyPossibleDuplicate(owner, ownerFieldsDto);
225	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
226	        this.clinicService.saveOwner(owner);
227	        applyHouseholdMemberCount(owner);
228	        auditOwnerCreated(owner);
229	        emitOwnerCreatedEvent(owner);
230	        enqueueWelcomeNotification(owner);
231	        return owner;
232	    }
233	
234	    /**
235	     * Enqueues a welcome notification for a freshly persisted owner by emitting a line to the
236	     * dedicated {@code NOTIFY} logger carrying the owner's {@code id} and its unified
237	     * {@code memberId}. This runs only on a successful create — once the owner has its generated
238	     * identity and derived member id — so downstream consumers watching the {@code NOTIFY} logger
239	     * can react to new members structurally.
240	     *
241	     * @param owner the persisted owner, already carrying its generated id and derived member id
242	     */
243	    private void enqueueWelcomeNotification(Owner owner) {
244	        NOTIFY.info("Welcome notification queued: id={} memberId={}",
245	            owner.getId(), owner.getMemberId());
246	    }
247	
248	    /**
249	     * Writes the human-readable {@code Owner created} audit line for a freshly persisted owner,
250	     * carrying its {@code id}, its unified {@code memberId}, its stored {@code registrationDate} and
251	     * its derived {@code membershipLevel}. This is the free-form companion to the structured
252	     * {@code OWNER_CREATED} event (see {@link #emitOwnerCreatedEvent(Owner)}); isolating it here
253	     * keeps {@link #createOwner(OwnerFieldsDto)} a thin orchestration and gives the audit line one
254	     * place to grow.
255	     *
256	     * @param owner the persisted owner, already carrying its generated id and derived values
257	     */
258	    private void auditOwnerCreated(Owner owner) {
259	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
260	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
261	            owner.getMembershipLevel());
262	    }
263	
264	    /**
265	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner,
266	     * alongside the human-readable audit line. The event is a JSON object carrying, in order, a
267	     * {@code seq} (a monotonically increasing integer across creates, see {@link #OWNER_CREATED_SEQ}),
268	     * the owner's {@code ownerId}, the owner's current primary identifier (see
269	     * {@link #primaryIdentifier(Owner)}) under the {@code memberId} key, the owner's derived
270	     * {@code membershipLevel}, and the {@code event} marker {@code 'OWNER_CREATED'}. Published to the
271	     * dedicated {@code AUDIT} logger so downstream consumers can react to owner creation structurally
272	     * rather than by parsing the free-form line.
273	     *
274	     * @param owner the persisted owner, already carrying its generated id and derived values
275	     */
276	    private void emitOwnerCreatedEvent(Owner owner) {
277	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
278	        Map<String, String> event = new java.util.LinkedHashMap<>();
279	        event.put("seq", Long.toString(seq));
280	        event.put("ownerId", String.valueOf(owner.getId()));
281	        event.put("memberId", jsonString(primaryIdentifier(owner)));
282	        event.put("membershipLevel", String.valueOf(owner.getMembershipLevel()));
283	        event.put("event", jsonString("OWNER_CREATED"));
284	        AUDIT.info("{}", jsonObject(event));
285	    }
286	
287	    /**
288	     * Returns the owner's current primary identifier, the single identity the structured
289	     * {@code OWNER_CREATED} event carries: the owner's unified {@code memberId}. This is the one seam
290	     * that decides which field is primary, so the event carries the member id under its
291	     * {@code memberId} key.
292	     *
293	     * @param owner the persisted owner whose primary identifier the event should carry
294	     * @return the owner's current primary identifier
295	     */
296	    private String primaryIdentifier(Owner owner) {
297	        return owner.getMemberId();
298	    }
299	
300	    /**
301	     * Renders a value as a JSON string literal for the structured audit event: {@code null} becomes
302	     * the JSON {@code null} keyword, otherwise the value is quoted with the JSON-significant
303	     * characters ({@code "} and {@code \}) escaped. The derived identifiers this carries never contain
304	     * such characters, but escaping keeps the emitted event valid JSON regardless.
305	     *
306	     * @param value the value to render, or {@code null}
307	     * @return the JSON representation of the value
308	     */
309	    private String jsonString(String value) {
310	        if (value == null) {
311	            return "null";
312	        }
313	        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
314	    }
315	
316	    /**
317	     * Assembles an ordered set of already-rendered fields into a compact JSON object literal for a
318	     * structured audit event: each entry becomes {@code "<key>":<value>} in insertion order, the
319	     * entries are joined by commas and wrapped in braces, with no whitespace. Values are inserted
320	     * verbatim, so a numeric field passes its bare digits (for example {@code String.valueOf(seq)})
321	     * and a string field passes its {@link #jsonString(String) quoted} form. This is the single
322	     * definition of how the structured audit events are serialized, so a new field is added by
323	     * putting one more entry on the ordered map rather than by editing a positional format string.
324	     *
325	     * @param fields the event's fields in the order they should appear, each value already rendered as JSON
326	     * @return the compact JSON object literal for the event
327	     */
328	    private String jsonObject(Map<String, String> fields) {
329	        return fields.entrySet().stream()
330	            .map(entry -> "\"" + entry.getKey() + "\":" + entry.getValue())
331	            .collect(Collectors.joining(",", "{", "}"));
332	    }
333	
334	    /**
335	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
336	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
337	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
338	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
339	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
340	     * it" and gives the created representation one place to grow.
341	     *
342	     * @param owner the persisted owner to render, carrying its generated id and stored fields
343	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
344	     */
345	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
346	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
347	        HttpHeaders headers = new HttpHeaders();
348	        headers.setLocation(UriComponentsBuilder.newInstance()
349	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
350	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
351	    }
352	
353	    /**
354	     * Renders a persisted owner as the {@code 200 OK} response shared by the read path
355	     * ({@link #getOwner(Integer)}) and the idempotent-replay path
356	     * ({@link #replayIdempotentCreate(String)}): the owner is stamped with its household member
357	     * count and then mapped to an {@link OwnerDto} carrying its {@code bulkSignupWarning} (see
358	     * {@link #toOwnerDtoWithWarning(Owner)}). Isolating the assembly here keeps both paths rendering
359	     * an existing owner identically rather than each copying the same steps.
360	     *
361	     * @param owner the persisted owner to render
362	     * @return the {@code 200 OK} response carrying the owner representation
363	     */
364	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
365	        applyHouseholdMemberCount(owner);
366	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
367	    }
368	
369	    /**
370	     * Maps a persisted owner to the {@link OwnerDto} returned by every rendered response, stamping
371	     * its {@code bulkSignupWarning} from the owner's stored {@code registrationDate} (see
372	     * {@link #bulkSignupWarning(LocalDate)}) and its {@code capacityWarning} from the owner's
373	     * {@code city} (see {@link #capacityWarning(String)}). This is the single definition of how an
374	     * owner becomes its response representation, shared by the read, idempotent-replay and create
375	     * responses, so all three derive the rendered fields identically rather than each copying the
376	     * mapping.
377	     *
378	     * @param owner the persisted owner to map
379	     * @return the owner representation with its {@code bulkSignupWarning} and {@code capacityWarning} set
380	     */
381	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
382	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
383	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
384	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
385	        ownerDto.setRiskFlag(riskFlag(owner));
386	        return ownerDto;
387	    }
388	
389	    /**
390	     * Reports whether an owner should be flagged for review. The flag is true when any of three
391	     * independent signals hold and false only when none does: the owner is a possible (soft)
392	     * duplicate (its {@code possibleDuplicate} flag is set, see
393	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}), the owner's email domain is
394	     * disposable-adjacent (see {@link #isDisposableAdjacentEmail(String)}) or the owner's city is
395	     * over its soft capacity (see {@link #capacityWarning(String)}). This is the single definition
396	     * of an owner's risk flag, shared by every rendered response.
397	     *
398	     * @param owner the persisted owner to assess
399	     * @return {@code true} when any risk signal holds, otherwise {@code false}
400	     */
401	    private boolean riskFlag(Owner owner) {
402	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
403	            || isDisposableAdjacentEmail(owner.getEmail())
404	            || capacityWarning(owner.getCity());
405	    }
406	
407	    /**
408	     * Reports whether an email's domain is disposable-adjacent: its domain (see
409	     * {@link #emailDomain(String)}) equals one of the known disposable domains (see
410	     * {@link #DISPOSABLE_EMAIL_DOMAINS}) or is a subdomain of one (it ends with {@code '.'} followed
411	     * by a disposable domain), compared case-insensitively. An exact disposable domain is already
412	     * rejected at intake by {@link #normalizeEmail(String)}, so a persisted owner reaches this rule
413	     * only through a subdomain of a disposable domain. An owner without an email has no domain and
414	     * is never disposable-adjacent.
415	     *
416	     * @param email the owner's stored email, or {@code null} when none was supplied
417	     * @return {@code true} when the email's domain is a disposable domain or a subdomain of one
418	     */
419	    private boolean isDisposableAdjacentEmail(String email) {
420	        String domain = emailDomain(email);
421	        if (domain == null) {
422	            return false;
423	        }
424	        return DISPOSABLE_EMAIL_DOMAINS.stream()
425	            .anyMatch(disposable -> domain.equals(disposable) || domain.endsWith("." + disposable));
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
431	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
432	        if (currentOwner == null) {
433	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	        }
435	        currentOwner.setAddress(ownerFieldsDto.getAddress());
436	        currentOwner.setCity(ownerFieldsDto.getCity());
437	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
438	        currentOwner.setLastName(ownerFieldsDto.getLastName());
439	        currentOwner.setTitle(ownerFieldsDto.getTitle());
440	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
441	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
442	        this.clinicService.saveOwner(currentOwner);
443	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
444	    }
445	
446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Transactional
448	    @Override
449	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
450	        Owner owner = this.clinicService.findOwnerById(ownerId);
451	        if (owner == null) {
452	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
