524	    /**
525	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
526	     * The address is normalized in place (so a required-field check that follows rejects an
527	     * address blank after normalization), the required fields are checked, the telephone and
528	     * email are normalized in place, and the resulting owner is rejected when its derived
529	     * identity key already belongs to another owner. Each rule
530	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
531	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
532	     * to be mapped and saved.
533	     *
534	     * @param ownerFieldsDto the submitted owner fields, normalized in place
535	     */
536	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
537	        applyAddress(ownerFieldsDto);
538	        validateRequiredFields(ownerFieldsDto);
539	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
540	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
541	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
542	        rejectDuplicateIdentity(ownerFieldsDto);
543	        rejectCityAtCapacity(ownerFieldsDto.getCity());
544	        rejectDailyLimitExceeded(registrationDate);
545	    }
