886	     * @param ownerFieldsDto the submitted owner fields
887	     */
888	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
889	        List<String> missing = new ArrayList<>();
890	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
891	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
892	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
893	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
894	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
895	        if (!missing.isEmpty()) {
896	            throw new RequiredFieldsMissingException(missing);
