906	    /**
907	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
908	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
909	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
910	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
911	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
912	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
913	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
914	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
915	     *
916	     * @param telephone the submitted telephone value
917	     * @return the normalized E.164 telephone
918	     */
919	    private String normalizeTelephone(String telephone) {
920	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
921	        String e164;
922	        if (cleaned.startsWith("+")) {
923	            e164 = "+" + cleaned.substring(1);
924	        } else {
925	            String national = cleaned;
926	            if (national.startsWith("0")) {
927	                national = national.substring(1);
928	            }
929	            e164 = "+61" + national;
930	        }
931	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
932	            throw new InvalidFieldsException(List.of("telephone"));
933	        }
934	        validateNationalNumberLength(e164);
935	        return e164;
936	    }
