949	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
950	     */
951	    private void validateNationalNumberLength(String e164) {
952	        String countryCode = Owner.countryCodeOf(e164);
953	        if (countryCode == null) {
954	            return;
955	        }
956	        int nationalLength = e164.length() - 1 - countryCode.length();
957	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
958	            throw new InvalidFieldsException(List.of("telephone"));
959	        }
960	    }
