964	     * and a domain containing at least one dot, none of the parts holding whitespace or a
965	     * second {@code @}.
966	     */
967	    private static final java.util.regex.Pattern EMAIL_PATTERN =
968	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
