970	    /**
971	     * Disposable email domains an owner may not register with. An email whose domain (compared
972	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
973	     */
974	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
975	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
