977	    /**
978	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
979	     * accepted and returned unchanged. When present it must be a syntactically valid address
980	     * whose domain is not on the disposable-domain blocklist (see
981	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
982	     * present but syntactically invalid or on a disposable domain an
983	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
984	     * response naming the {@code email} field.
985	     *
986	     * @param email the submitted email value, or {@code null} when omitted
987	     * @return the lower-cased email, or {@code null} when none was supplied
988	     */
989	    private String normalizeEmail(String email) {
990	        if (email == null) {
991	            return null;
992	        }
993	        String trimmed = email.trim();
994	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
995	            throw new InvalidFieldsException(List.of("email"));
996	        }
997	        String domain = emailDomain(trimmed);
998	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
999	            throw new InvalidFieldsException(List.of("email"));
1000	        }
1001	        return canonicalEmail(trimmed);
1002	    }
