1004	    /**
1005	     * Reduces an email to the canonical form used both to store it and to compare it against
1006	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
1007	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
1008	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
1009	     * value read back off an existing owner without risk of rejecting it. This is the single
1010	     * definition of email identity: two emails denote the same address exactly when they
1011	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
1012	     * an email already on an existing owner can be compared for equality after both pass through
1013	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
1014	     *
1015	     * @param email the email to canonicalize, or {@code null} when none was supplied
1016	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
1017	     */
1018	    private String canonicalEmail(String email) {
1019	        if (email == null) {
1020	            return null;
1021	        }
1022	        return email.trim().toLowerCase(java.util.Locale.ROOT);
1023	    }
