1025	    /**
1026	     * Extracts the lower-cased domain of an email — everything after its final {@code '@'}. This is
1027	     * the single definition of an email's domain, shared wherever an owner's email is matched by its
1028	     * domain (for example the disposable-domain blocklist applied in {@link #normalizeEmail(String)}),
1029	     * so every such rule reads the domain identically rather than re-deriving it. A {@code null} email
1030	     * (none was supplied) has no domain and yields {@code null}. Like {@link #canonicalEmail(String)}
1031	     * no validation is performed, so this can be applied to a value read back off an existing owner as
1032	     * readily as to one being normalized; a caller that needs a syntactically valid address validates
1033	     * it first. The domain is lower-cased so it compares case-insensitively, matching how
1034	     * {@link #DISPOSABLE_EMAIL_DOMAINS} is compared. For example {@code "jane@Example.COM"} yields
1035	     * {@code "example.com"}.
1036	     *
1037	     * @param email the email whose domain to extract, or {@code null} when none was supplied
1038	     * @return the lower-cased domain, or {@code null} when {@code email} is {@code null}
1039	     */
1040	    private String emailDomain(String email) {
1041	        if (email == null) {
1042	            return null;
1043	        }
1044	        return email.substring(email.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
1045	    }
