1047	    /**
1048	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
1049	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
1050	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
1051	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
1052	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
1053	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
1054	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
1055	     * 400 response naming the {@code postcode} field.
1056	     *
1057	     * @param postcode the submitted postcode, or {@code null} when omitted
1058	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
1059	     */
1060	    private void validatePostcode(String postcode, String city) {
1061	        if (postcode == null) {
1062	            return;
1063	        }
1064	        if (!postcode.matches("^[0-9]{4}$")) {
1065	            throw new InvalidFieldsException(List.of("postcode"));
1066	        }
1067	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
1068	        if (range != null) {
1069	            int value = Integer.parseInt(postcode);
1070	            if (value < range[0] || value > range[1]) {
1071	                throw new InvalidFieldsException(List.of("postcode"));
1072	            }
1073	        }
1074	    }
