1076	    /**
1077	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
1078	     * identity is its single derived identity key (see
1079	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
1080	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
1081	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
1082	     * owner carries the same identity key. The email-domain blocklist has already been applied when
1083	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
1084	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
1085	     * name and postcode) but carry different telephones now have distinct identity keys and are not
1086	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
1087	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
1088	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
1089	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
1090	     * deliberate household member and bypasses this block.
1091	     *
1092	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
1093	     */
1094	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
1095	        if (sharesHousehold(ownerFieldsDto)) {
1096	            return;
1097	        }
1098	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
1099	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
1100	        boolean taken = this.clinicService.findAllOwners().stream()
1101	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1102	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
1103	        if (taken) {
1104	            throw new DuplicateIdentityException(identityKey);
1105	        }
1106	    }
