844	     * Returns this owner's age band, derived from {@code birthDate} computed against
845	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
846	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
847	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
848	     * band cannot be derived. This is the single definition of an owner's age band.
849	     *
850	     * @return the owner's age band, or {@code null} when it cannot be derived
851	     */
852	    @Transient
853	    public String getAgeBand() {
854	        if (this.birthDate == null || this.registrationDate == null) {
855	            return null;
856	        }
857	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
858	        if (age < 18) {
859	            return "MINOR";
860	        }
861	        if (age < 65) {
862	            return "ADULT";
863	        }
864	        return "SENIOR";
865	    }
