14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's {@code selfLink}: the canonical URI path of the owner, formed as
33	     * {@code '/api/owners/'} followed by its id. Returns {@code null} when the owner has no id
34	     * yet, leaving {@code selfLink} absent from the response.
35	     */
36	    default String selfLink(Owner owner) {
37	        if (owner == null || owner.getId() == null) {
38	            return null;
39	        }
40	        return "/api/owners/" + owner.getId();
41	    }
42	
43	    /**
44	     * Derives the owner's age band as the DTO enum, rendering the owner's derived age band (see
45	     * {@link Owner#getAgeBand()}). Returns {@code null} when the owner has no derivable age band
46	     * (no birthDate or no registrationDate), leaving {@code ageBand} absent from the response.
47	     */
48	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
49	        if (owner == null || owner.getAgeBand() == null) {
50	            return null;
51	        }
52	        return OwnerDto.AgeBandEnum.valueOf(owner.getAgeBand());
53	    }
54	
55	    /**
56	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
57	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
58	     */
59	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        return Owner.hasEmail(owner.getEmail())
64	            ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
65	    }
66	
67	    /**
68	     * Derives the owner's segment as {@code '<TIER>_<AREA>'}. TIER is {@code 'PREMIUM'} when the
69	     * owner's derived {@code membershipLevel} (see {@link Owner#getMembershipLevel()}) is 3 or more,
70	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known
71	     * region ({@code NSW}, {@code VIC} or {@code QLD}; see {@link #localityRegion(Owner)}), otherwise
72	     * {@code 'REGIONAL'}.
73	     */
74	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
75	        if (owner == null) {
76	            return null;
77	        }
78	        Integer level = owner.getMembershipLevel();
79	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
80	        String region = localityRegion(owner);
81	        String area = (region != null && REGION_TIMEZONES.containsKey(region)) ? "METRO" : "REGIONAL";
82	        return OwnerDto.OwnerSegmentEnum.valueOf(tier + "_" + area);
83	    }
84	
85	    /**
86	     * Derives the owner's locality from the region its identity carries (see
87	     * {@link #localityRegion(Owner)}). Returns that region string, or {@code 'UNKNOWN'} when the
88	     * owner has no known region.
89	     */
90	    default String locality(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        String region = localityRegion(owner);
95	        return region != null ? region : "UNKNOWN";
96	    }
97	
98	    /**
99	     * Resolves the region an owner's {@link #locality(Owner)} is derived from: the owner's own region
100	     * (see {@link Owner#getRegion()}), reported only once the owner has been assigned its identity
101	     * (its {@code memberId} is present). Only the known regions ({@code NSW}, {@code VIC},
102	     * {@code QLD}) — the ones carrying a timezone entry — are returned; the sentinel {@code 'UNKNOWN'}
103	     * region (used when the owner has no known region) and a missing member id both resolve to
104	     * {@code null}. Reading the region straight from the owner keeps the user-facing locality
105	     * independent of how the owner's identifiers encode their region, so the identifier encoding can
106	     * change without disturbing this plain region. Keeping the region source in its own method leaves
107	     * {@link #locality(Owner)} owning only the {@code null -> 'UNKNOWN'} rendering, so where the
108	     * region itself comes from can change without disturbing that rendering.
109	     *
110	     * @param owner the owner whose locality region is resolved, never {@code null}
111	     * @return the region string, or {@code null} when the owner has no known region
112	     */
113	    default String localityRegion(Owner owner) {
114	        if (owner.getMemberId() == null) {
115	            return null;
116	        }
117	        String region = owner.getRegion();
118	        return region != null && REGION_TIMEZONES.containsKey(region) ? region : null;
119	    }
120	
121	    /**
122	     * Fixed region-to-timezone table: the IANA timezone name each known region maps to
123	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
124	     * {@code QLD -> Australia/Brisbane}). A region absent from this table has no known timezone.
125	     */
126	    java.util.Map<String, String> REGION_TIMEZONES = java.util.Map.of(
127	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
128	
129	    /**
130	     * Derives the owner's IANA timezone from the region its identity carries (see
131	     * {@link #localityRegion(Owner)}) using the fixed region-to-timezone table
132	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
133	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the owner has no known region
134	     * or the region has no timezone entry, leaving {@code timezone} absent from the response.
135	     */
136	    default String timezone(Owner owner) {
137	        if (owner == null) {
138	            return null;
139	        }
140	        String region = localityRegion(owner);
141	        return region == null ? null : REGION_TIMEZONES.get(region);
142	    }
143	
144	    /**
145	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
146	     */
147	    default String displayName(Owner owner) {
148	        if (owner == null) {
149	            return null;
150	        }
151	        return owner.getLastName() + ", " + owner.getFirstName();
152	    }
153	
154	    /**
155	     * Returns the owner's initials as the upper-cased first letters of firstName and
156	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
157	     */
158	    default String initials(Owner owner) {
159	        if (owner == null) {
160	            return null;
161	        }
162	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
163	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
164	    }
165	
166	    Owner toOwner(OwnerDto ownerDto);
167	
168	    @Mapping(target = "id", ignore = true)
169	    @Mapping(target = "pets", ignore = true)
170	    Owner toOwner(OwnerFieldsDto ownerDto);
171	
172	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
173	
174	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
175	
